 @page "/notepad"
 @rendermode InteractiveServer
 @inject IJSRuntime JS
 @implements IAsyncDisposable

 <PageTitle>Notepad</PageTitle>

 <h1>Notepad</h1>

 <textarea @bind="Content" @bind:event="oninput" @bind:after="OnContentChanged"
           rows="12" class="form-control mb-3" placeholder="Type your notes here…"></textarea>

 <div class="d-flex align-items-center gap-2">
     <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
     <button class="btn btn-outline-danger" @onclick="ClearAsync">Clear</button>
     @if (_lastSavedAt is not null)
     {
         <span class="text-muted ms-2">Last saved at @_lastSavedAt.Value.ToString("HH:mm:ss")</span>
     }
 </div>

 @code {
     private string Content { get; set; } = string.Empty;
     private DateTime? _lastSavedAt;
     private NotepadInterop? _interop;
     private DotNetObjectReference<Notepad>? _dotNetRef;

     protected override async Task OnAfterRenderAsync(bool firstRender)
     {
         if (firstRender)
         {
             _interop = new NotepadInterop(JS);
             _dotNetRef = DotNetObjectReference.Create(this);
             var saved = await _interop.InitializeAsync(_dotNetRef);
             if (!string.IsNullOrEmpty(saved))
             {
                 Content = saved;
                 StateHasChanged();
             }
         }
     }

     private async Task OnContentChanged()
     {
         if (_interop is not null)
         {
             await _interop.MarkDirtyAsync();
         }
     }

     [JSInvokable("OnAutoSave")]
     public async Task OnAutoSave()
     {
         await InvokeAsync(async () =>
         {
             await SaveContentAsync();
             StateHasChanged();
         });
     }

     private async Task SaveNowAsync() => await SaveContentAsync();

     private async Task SaveContentAsync()
     {
         if (_interop is not null)
         {
             await _interop.SaveAsync(Content);
             _lastSavedAt = DateTime.Now;
         }
     }

     private async Task ClearAsync()
     {
         if (_interop is not null)
         {
             Content = string.Empty;
             _lastSavedAt = null;
             await _interop.ClearAsync();
         }
     }

     public async ValueTask DisposeAsync()
     {
         if (_interop is not null)
             await _interop.DisposeAsync();
         _dotNetRef?.Dispose();
     }
 }

